sub get_body_chunk {
  my ($self, $offset) = @_;
  return $self->generate_body_chunk($offset) if $self->is_dynamic;

  my $boundary = $self->build_boundary;
  my $boundary_len = length($boundary) + 6; # "--$boundary\r\n" or "--$boundary--\r\n"
  my $parts = $self->parts;
  my $total_offset = 0;

  foreach my $part (@$parts) {
    my $part_header_size = $part->header_size;
    my $part_body_size = $part->body_size;

    # Check if the offset is within the current part's header
    if ($offset >= $total_offset && $offset < $total_offset + $part_header_size) {
      my $header_chunk = $part->get_header_chunk($offset - $total_offset);
      return $header_chunk;
    }

    # Check if the offset is within the current part's body
    if ($offset >= $total_offset + $part_header_size && $offset < $total_offset + $part_header_size + $part_body_size) {
      my $body_chunk = $part->get_body_chunk($offset - $total_offset - $part_header_size);
      return $body_chunk;
    }

    # Move to the next part, including the boundary
    $total_offset += $part_header_size + $part_body_size + $boundary_len;
  }

  # If the offset is at the very end, return the closing boundary
  if ($offset == $total_offset - $boundary_len) {
    return "--$boundary--\r\n";
  }

  # If the offset is beyond the last boundary, return nothing
  return '';
}
