    $tree->[1] = { %{ $tree->[1] // {} }, %{ $_[0] } };
    return $self;
  }

  # Set single attribute
  if (@_ == 2) {
    $tree->[1]->{$_[0]} = $_[1];
    return $self;
  }

  # Get single attribute
  return $tree->[1]->{$_[0]} if @$tree == 2 && exists $tree->[1]->{$_[0]};

  return undef;
}
