my ($self, $name) = (shift, shift);
my $subscribers = $self->subscribers($name);
unless ($subscribers) {
    return $self;
}
my @args = @_;
foreach my $cb (@$subscribers) {
    my $error_caught;
    {
        local $@;
        eval {
            $cb->($self, @args);
            1;
        } or do {
            $error_caught = $@;
        };
    }
    if ($error_caught) {
        $self->emit('error', $error_caught) unless $name eq 'error';
    }
}
return $self;
}

