my ($ns, $options) = (shift, shift // {});
my $base_path = class_to_path $ns;
my $file = path($base_path)->to_rel(path());

my @modules;
if ($options->{recursive}) {
  @modules = $file->list_tree({dir => 0, hidden => 0})->each(sub {
    my $path = shift;
    my $module = $path->to_rel($file)->to_string;
    $module =~ s!/!::!g;
    $module =~ s/\.pm$//;
    push @modules, "$ns\::$module" if $module;
  });
} else {
  @modules = $file->list({dir => 0, hidden => 0})->each(sub {
    my $path = shift;
    my $module = $path->to_rel($file)->to_string;
    $module =~ s/\.pm$//;
    push @modules, "$ns\::$module" if $module;
  });
}

return @modules;
}
