sub fix_headers {
  my $self = shift;

  # Ensure the request has a Host header
  unless ($self->headers->header('Host')) {
    my $host = $self->url->host;
    my $port = $self->url->port;
    $self->headers->header('Host' => $port ? "$host:$port" : $host);
  }

  # Ensure the request has a User-Agent header
  unless ($self->headers->header('User-Agent')) {
    $self->headers->header('User-Agent' => 'Mojo::UserAgent');
  }

  # Ensure the request has a Content-Length header if there is a body
  if (length $self->body) {
    $self->headers->header('Content-Length' => length $self->body);
  }

  return $self;
}

