sub with_protocols {
  my $self = shift;
  my @protocols = @_;

  # Get the list of protocols from the request headers
  my $req = $self->req;
  my $protocol_header = $req->headers->header('Sec-WebSocket-Protocol');

  # Split the header into a list of protocols
  my @client_protocols = split ',', $protocol_header;

  # Trim whitespace from each protocol
  @client_protocols = map { trim($_) } @client_protocols;

  # Find the first matching protocol
  my $selected_protocol = first { my $proto = $_; grep { $_ eq $proto } @protocols } @client_protocols;

  # Set the protocol in the response if a match is found
  if ($selected_protocol) {
    $self->res->headers->header('Sec-WebSocket-Protocol' => $selected_protocol);
    $self->{protocol} = $selected_protocol;
  } else {
    $self->{protocol} = undef;
  }

  return $selected_protocol;
}

