  my ($self, $head, $path) = @_;

  # Check if the HEAD request was successful
  return $head unless $head->is_success;

  # Get the file size from the Content-Length header
  my $size = $head->res->headers->content_length;
  return $head unless defined $size;

  # Create a file asset for the download
  my $asset = Mojo::Asset::File->new(path => $path);

  # Open the file for writing and seek to the end to resume if possible
  my $handle = $asset->open('>>');
  seek $handle, 0, 2;
  my $offset = tell $handle;

  # Create a new HTTP transaction for the download
  my $tx = Mojo::Transaction::HTTP->new;
  $tx->req->method('GET');
  $tx->req->url->parse($head->req->url);

  # Set the Range header to resume the download
  $tx->req->headers->range("bytes=$offset-");

  # Set the response content asset
  $tx->res->content->asset($asset);

  return $tx;
}

