my $file = @_ ? "$_[0]" : (caller)[1];
open my $fh, '<', $file or croak qq{Can't open file "$file": $!};
local $/ = undef;
my $content = <$fh>;
close $fh;

if ($content =~ /=head1\s+SYNOPSIS\s+(.*?)\n(=head1|\z)/sm) {
    my $synopsis = $1;
    if ($synopsis =~ /Usage:\s+(.*)/m) {
        my $usage = $1;
        $usage =~ s/\n+/\n/g;
        $usage = unindent($usage);
        return $usage . "\n";
    }
}
return '';
}
