        $t = $base - 1 if $t > $base - 1;
        $t = $tmin if $t < $tmin;
        push @output, $basic[$t];
        last if $q < $base - $tmin;
        $q = int(($q - ($base - $tmin)) / ($base - $tmin));
      }
      push @output, $basic[$q];
      $bias = _adapt(1, $h + 1, 1);
      $h++;
    }
    $b++;
